   821	torch::Tensor direct_cholesky(
   822	        torch::Tensor input,
   823	        torch::Tensor output,
   824	        torch::Tensor pointers,
   825	        torch::Tensor info,
   826	        torch::Tensor workspace) {
   827	    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
   828	    TORCH_CHECK(input.scalar_type() == at::kFloat, "input must be float32");
   829	    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
   830	    TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
   831	                "input must be a batch of square matrices");
   832	    TORCH_CHECK(output.is_cuda() && output.scalar_type() == at::kFloat,
   833	                "output must be CUDA float32");
   834	    TORCH_CHECK(output.is_contiguous() && output.sizes() == input.sizes(),
   835	                "output must be a same-sized contiguous tensor");
   836	
   837	    const int batch = static_cast<int>(input.size(0));
   838	    const int n = static_cast<int>(input.size(1));
   839	    // cuSOLVER's column-major lower triangle is the row-major upper triangle.
   840	    // Copy just that source triangle and zero the unused half in one kernel.
   841	    at::triu_out(output, input, 0);
   842	    TORCH_CHECK(info.is_cuda() && info.scalar_type() == at::kInt &&
   843	                info.numel() == batch, "invalid info tensor");
   844	    auto handle = at::cuda::getCurrentCUDASolverDnHandle();
   845	    check_cusolver(
   846	        cusolverDnSetMathMode(handle, CUSOLVER_FP32_EMULATED_BF16X9_MATH),
   847	        "cusolverDnSetMathMode");
   848	
   849	    const bool use_looped = batch <= 4 && n >= 1024;
   850	    if (!use_looped) {
   851	        TORCH_CHECK(pointers.is_cuda() &&
   852	                    pointers.scalar_type() == at::kLong &&
   853	                    pointers.numel() == batch, "invalid pointer array");
   854	        check_cusolver(
   855	            cusolverDnSpotrfBatched(
   856	                handle, CUBLAS_FILL_MODE_LOWER, n,
   857	                reinterpret_cast<float**>(pointers.data_ptr<int64_t>()), n,
   858	                info.data_ptr<int>(), batch),
   859	            "cusolverDnSpotrfBatched");
   860	    } else {
   861	        TORCH_CHECK(workspace.is_cuda() &&
   862	                    workspace.scalar_type() == at::kFloat,
   863	                    "invalid workspace tensor");
   864	        const int64_t matrix_stride = static_cast<int64_t>(n) * n;
   865	        for (int i = 0; i < batch; ++i) {
   866	            check_cusolver(
   867	                cusolverDnSpotrf(
   868	                    handle, CUBLAS_FILL_MODE_LOWER, n,
   869	                    output.data_ptr<float>() + i * matrix_stride, n,
   870	                    workspace.data_ptr<float>(), workspace.numel(),
   871	                    info.data_ptr<int>() + i),
   872	                "cusolverDnSpotrf");
   873	        }
   874	    }
   875	
   876	    // The row-major upper factor becomes an F-contiguous lower-triangular view.
   877	    return output.transpose(-2, -1);
   878	}
