   880	torch::Tensor grouped_blocked_cholesky(
   881	        torch::Tensor input,
   882	        torch::Tensor output,
   883	        torch::Tensor pointers,
   884	        torch::Tensor info,
   885	        int64_t block_size) {
   886	    TORCH_CHECK(input.is_cuda() && output.is_cuda(), "CUDA tensors required");
   887	    TORCH_CHECK(input.scalar_type() == at::kFloat &&
   888	                output.scalar_type() == at::kFloat, "FP32 tensors required");
   889	    TORCH_CHECK(input.is_contiguous() && output.is_contiguous() &&
   890	                input.sizes() == output.sizes(), "invalid matrix buffers");
   891	    TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
   892	                "square matrix batches required");
   893	
   894	    const int batch = static_cast<int>(input.size(0));
   895	    const int n = static_cast<int>(input.size(1));
   896	    const int block = static_cast<int>(block_size);
   897	    const int panels = (n + block - 1) / block;
   898	    TORCH_CHECK(block > 0 && block <= n, "invalid block size");
   899	    TORCH_CHECK(pointers.is_cuda() &&
   900	                pointers.scalar_type() == at::kLong &&
   901	                pointers.numel() == static_cast<int64_t>(panels) * 2 * batch,
   902	                "invalid grouped pointer tables");
   903	    TORCH_CHECK(info.is_cuda() && info.scalar_type() == at::kInt &&
   904	                info.numel() == batch, "invalid info tensor");
   905	
   906	    // Treat row-major upper storage as column-major lower storage.
   907	    at::triu_out(output, input, 0);
   908	    auto solver = at::cuda::getCurrentCUDASolverDnHandle();
   909	    auto blas = at::cuda::getCurrentCUDABlasHandle();
   910	    check_cusolver(
   911	        cusolverDnSetMathMode(solver, CUSOLVER_FP32_EMULATED_BF16X9_MATH),
   912	        "cusolverDnSetMathMode");
   913	
   914	    const float one = 1.0f;
   915	    const float minus_one = -1.0f;
   916	    const int64_t matrix_stride = static_cast<int64_t>(n) * n;
   917	    auto pointer_data = pointers.data_ptr<int64_t>();
   918	    float* output_data = output.data_ptr<float>();
   919	
   920	    for (int panel_index = 0, k = 0; k < n;
   921	         ++panel_index, k += block) {
   922	        const int width = std::min(block, n - k);
   923	        const int stop = k + width;
   924	        float** diagonal = reinterpret_cast<float**>(
   925	            pointer_data + static_cast<int64_t>(panel_index) * 2 * batch
   926	        );
   927	        check_cusolver(
   928	            cusolverDnSpotrfBatched(
   929	                solver, CUBLAS_FILL_MODE_LOWER, width, diagonal, n,
   930	                info.data_ptr<int>(), batch),
   931	            "grouped diagonal potrf");
   932	        if (stop == n) {
   933	            continue;
   934	        }
   935	
   936	        const int trailing = n - stop;
   937	        float* const* panel = reinterpret_cast<float* const*>(
   938	            pointer_data +
   939	            static_cast<int64_t>(panel_index) * 2 * batch + batch
   940	        );
   941	        check_cublas(
   942	            cublasStrsmBatched(
   943	                blas, CUBLAS_SIDE_RIGHT, CUBLAS_FILL_MODE_LOWER,
   944	                CUBLAS_OP_T, CUBLAS_DIAG_NON_UNIT,
   945	                trailing, width, &one,
   946	                reinterpret_cast<const float* const*>(diagonal), n,
   947	                panel, n, batch),
   948	            "grouped panel trsm");
   949	
   950	        float* first_panel = output_data +
   951	            static_cast<int64_t>(k) * n + stop;
   952	        float* first_trailing = output_data +
   953	            static_cast<int64_t>(stop) * n + stop;
   954	        check_cublas(
   955	            cublasGemmStridedBatchedEx(
   956	                blas, CUBLAS_OP_N, CUBLAS_OP_T,
   957	                trailing, trailing, width,
   958	                &minus_one,
   959	                first_panel, CUDA_R_32F, n, matrix_stride,
   960	                first_panel, CUDA_R_32F, n, matrix_stride,
   961	                &one,
   962	                first_trailing, CUDA_R_32F, n, matrix_stride,
   963	                batch, CUBLAS_COMPUTE_32F_FAST_TF32,
   964	                CUBLAS_GEMM_DEFAULT_TENSOR_OP),
   965	            "grouped trailing gemm");
   966	    }
   967	
   968	    // Full GEMMs touched both halves; retain only the physical upper factor.
   969	    at::triu_out(output, output, 0);
   970	    return output.transpose(-2, -1);
   971	}
