2510	            value = fmaf(-row_values[j], tile[K * LD + j], value);
2511	        }
2512	    }
2513	
2514	    if (active && lane == K) {
2515	        const float diagonal = sqrtf(fmaxf(value, 1.0e-30f));
2516	        row_values[K] = diagonal;
2517	        tile[K * LD + K] = diagonal;
2518	        inverse[group] = 1.0f / diagonal;
2519	    }
2520	    __syncthreads();
2521	
2522	    if (active && lane > K) {
2523	        value *= inverse[group];
2524	        row_values[K] = value;
2525	        tile[lane * LD + K] = value;
2526	    }
2527	    __syncthreads();
2528	
2529	    if constexpr (K + 1 < 64) {
2530	        register_cholesky_step_64<K + 1>(
2531	            row_values, tile, inverse, group, lane, active
2532	        );
2533	    }
2534	}
