2536	__global__ void grouped_two_cholesky_64(
2537	    const float* __restrict__ input,
2538	    float* __restrict__ output,
2539	    int batch
2540	) {
2541	    constexpr int N = 64;
2542	    constexpr int LD = 65;
2543	    constexpr int MATRICES_PER_BLOCK = 4;
2544	    extern __shared__ float scratch[];
2545	    float* inverse = scratch;
2546	    float* storage = scratch + MATRICES_PER_BLOCK;
2547	    const int group = threadIdx.x / N;
2548	    const int lane = threadIdx.x % N;
2549	    const int matrix = static_cast<int>(blockIdx.x) * MATRICES_PER_BLOCK + group;
2550	    const bool active = matrix < batch;
2551	    float* tile = storage + group * N * LD;
2552	
2553	    if (active) {
2554	        const int base = matrix * N * N;
2555	        const float* src = input + base;
2556	        #pragma unroll
2557	        for (int row = 0; row < N; ++row) {
2558	            tile[row * LD + lane] = row >= lane
2559	                ? src[row * N + lane]
2560	                : 0.0f;
2561	        }
2562	    }
2563	    __syncthreads();
2564	
2565	    float row_values[N];
2566	    #pragma unroll
2567	    for (int col = 0; col < N; ++col) {
2568	        row_values[col] = active ? tile[lane * LD + col] : 0.0f;
2569	    }
2570	    register_cholesky_step_64<0>(
2571	        row_values, tile, inverse, group, lane, active
2572	    );
2573	
2574	    if (active) {
2575	        const int base = matrix * N * N;
2576	        float* dst = output + base;
2577	        #pragma unroll
2578	        for (int row = 0; row < N; ++row) {
2579	            dst[row * N + lane] = tile[row * LD + lane];
2580	        }
2581	    }
2582	}
