2584	__device__ __forceinline__ void factor_panel_16_warp(
2585	    float* tile,
2586	    int panel
2587	) {
2588	    constexpr int N = 128;
2589	    const int lane = threadIdx.x % 32;
2590	    if (lane < 16) {
2591	        float row_values[16];
2592	        #pragma unroll
2593	        for (int col = 0; col < 16; ++col) {
2594	            row_values[col] = lane >= col
2595	                ? tile[(panel + lane) * N + panel + col]
2596	                : 0.0f;
2597	        }
2598	
2599	        #pragma unroll
2600	        for (int pivot = 0; pivot < 16; ++pivot) {
2601	            float value = row_values[pivot];
2602	            #pragma unroll
2603	            for (int col = 0; col < pivot; ++col) {
2604	                const float pivot_value = __shfl_sync(
2605	                    0x0000ffff, row_values[col], pivot, 16
2606	                );
2607	                if (lane >= pivot) {
2608	                    value = fmaf(-row_values[col], pivot_value, value);
2609	                }
2610	            }
2611	            float inverse = 0.0f;
2612	            if (lane == pivot) {
2613	                const float diagonal = sqrtf(fmaxf(value, 1.0e-30f));
2614	                row_values[pivot] = diagonal;
2615	                inverse = 1.0f / diagonal;
2616	            }
2617	            inverse = __shfl_sync(0x0000ffff, inverse, pivot, 16);
2618	            if (lane > pivot) {
2619	                row_values[pivot] = value * inverse;
2620	            }
2621	        }
2622	
2623	        #pragma unroll
2624	        for (int col = 0; col < 16; ++col) {
2625	            if (lane >= col) {
2626	                tile[(panel + lane) * N + panel + col] = row_values[col];
2627	            }
2628	        }
2629	    }
2630	}
