2632	__device__ __forceinline__ void factor_panel_16(
2633	    float* tile,
2634	    int panel
2635	) {
2636	    if (threadIdx.x / 32 == 0) {
2637	        factor_panel_16_warp(tile, panel);
2638	    }
2639	    __syncthreads();
2640	}
