2642	__device__ __forceinline__ void solve_panel_16(
2643	    float* tile,
2644	    int panel
2645	) {
2646	    constexpr int N = 128;
2647	    constexpr int TEAM_WIDTH = 4;
2648	    const int team = threadIdx.x / TEAM_WIDTH;
2649	    const int lane = threadIdx.x % TEAM_WIDTH;
2650	    const int stop = panel + 16;
2651	    const int row = stop + team;
2652	    const bool active = row < N;
2653	    float row_values[4];
2654	    #pragma unroll
2655	    for (int item = 0; item < 4; ++item) {
2656	        row_values[item] = active
2657	            ? tile[row * N + panel + item * TEAM_WIDTH + lane]
2658	            : 0.0f;
2659	    }
2660	    #pragma unroll
2661	    for (int pivot = 0; pivot < 16; ++pivot) {
2662	        float dot = 0.0f;
2663	        #pragma unroll
2664	        for (int item = 0; item < 4; ++item) {
2665	            const int col = item * TEAM_WIDTH + lane;
2666	            if (col < pivot) {
2667	                dot = fmaf(
2668	                    row_values[item],
2669	                    tile[(panel + pivot) * N + panel + col],
2670	                    dot
2671	                );
2672	            }
2673	        }
2674	        dot += __shfl_down_sync(0xffffffff, dot, 2, TEAM_WIDTH);
2675	        dot += __shfl_down_sync(0xffffffff, dot, 1, TEAM_WIDTH);
2676	        float original = __shfl_sync(
2677	            0xffffffff,
2678	            row_values[pivot / TEAM_WIDTH],
2679	            pivot % TEAM_WIDTH,
2680	            TEAM_WIDTH
2681	        );
2682	        float solved = lane == 0
2683	            ? (original - dot)
2684	                / tile[(panel + pivot) * N + panel + pivot]
2685	            : 0.0f;
2686	        solved = __shfl_sync(0xffffffff, solved, 0, TEAM_WIDTH);
2687	        if (lane == pivot % TEAM_WIDTH) {
2688	            row_values[pivot / TEAM_WIDTH] = solved;
2689	        }
2690	    }
2691	    if (active) {
2692	        #pragma unroll
2693	        for (int item = 0; item < 4; ++item) {
2694	            tile[row * N + panel + item * TEAM_WIDTH + lane] =
2695	                row_values[item];
2696	        }
2697	    }
2698	    __syncthreads();
2699	}
