2701	__device__ __forceinline__ void compensated_rankk_16(
2702	    float* tile,
2703	    int panel
2704	) {
2705	    constexpr int N = 128;
2706	    constexpr int WARPS = 16;
2707	    constexpr int MMA_M = 16;
2708	    constexpr int MMA_N = 16;
2709	    constexpr int MMA_K = 8;
2710	    constexpr float RESIDUAL_SCALE = 32.0f;
2711	    constexpr float INVERSE_RESIDUAL_SCALE = 1.0f / RESIDUAL_SCALE;
2712	    const int warp = threadIdx.x / 32;
2713	    const int stop = panel + 16;
2714	    const int tile_count = (N - stop) / MMA_M;
2715	    int ordinal = 0;
2716	    for (int block_row = 0; block_row < tile_count; ++block_row) {
2717	        for (int block_col = 0; block_col <= block_row; ++block_col) {
2718	            if (ordinal % WARPS == warp) {
2719	                {
2720	                wmma::fragment<
2721	                    wmma::matrix_a, MMA_M, MMA_N, MMA_K,
2722	                    wmma::precision::tf32, wmma::row_major
2723	                > a_high;
2724	                wmma::fragment<
2725	                    wmma::matrix_a, MMA_M, MMA_N, MMA_K,
2726	                    wmma::precision::tf32, wmma::row_major
2727	                > a_scaled;
2728	                wmma::fragment<
2729	                    wmma::matrix_b, MMA_M, MMA_N, MMA_K,
2730	                    wmma::precision::tf32, wmma::col_major
2731	                > b_high;
2732	                wmma::fragment<
2733	                    wmma::matrix_b, MMA_M, MMA_N, MMA_K,
2734	                    wmma::precision::tf32, wmma::col_major
2735	                > b_scaled;
2736	                wmma::fragment<
2737	                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
2738	                > high_product;
2739	                wmma::fragment<
2740	                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
2741	                > scaled_product;
2742	                wmma::fragment<
2743	                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
2744	                > accumulator;
2745	                wmma::fill_fragment(high_product, 0.0f);
2746	                wmma::fill_fragment(scaled_product, 0.0f);
2747	                #pragma unroll
2748	                for (int offset = 0; offset < 16; offset += MMA_K) {
2749	                    wmma::load_matrix_sync(
2750	                        a_high,
2751	                        tile + (stop + block_row * MMA_M) * N
2752	                            + panel + offset,
2753	                        N
2754	                    );
2755	                    wmma::load_matrix_sync(
2756	                        b_high,
2757	                        tile + (stop + block_col * MMA_N) * N
2758	                            + panel + offset,
2759	                        N
2760	                    );
2761	                    #pragma unroll
2762	                    for (int element = 0;
2763	                         element < a_high.num_elements;
2764	                         ++element) {
2765	                        const float original = a_high.x[element];
2766	                        const float high = wmma::__float_to_tf32(original);
2767	                        a_high.x[element] = high;
2768	                        a_scaled.x[element] = wmma::__float_to_tf32(
2769	                            fmaf(RESIDUAL_SCALE, original - high, high)
2770	                        );
2771	                    }
2772	                    #pragma unroll
2773	                    for (int element = 0;
2774	                         element < b_high.num_elements;
2775	                         ++element) {
2776	                        const float original = b_high.x[element];
2777	                        const float high = wmma::__float_to_tf32(original);
2778	                        b_high.x[element] = high;
2779	                        b_scaled.x[element] = wmma::__float_to_tf32(
2780	                            fmaf(RESIDUAL_SCALE, original - high, high)
2781	                        );
2782	                    }
2783	                    wmma::mma_sync(
2784	                        high_product, a_high, b_high, high_product
2785	                    );
2786	                    wmma::mma_sync(
2787	                        scaled_product,
2788	                        a_scaled,
2789	                        b_scaled,
2790	                        scaled_product
2791	                    );
2792	                }
2793	                wmma::load_matrix_sync(
2794	                    accumulator,
2795	                    tile + (stop + block_row * MMA_M) * N
2796	                        + stop + block_col * MMA_N,
2797	                    N,
2798	                    wmma::mem_row_major
2799	                );
2800	                #pragma unroll
2801	                for (int element = 0;
2802	                     element < accumulator.num_elements;
2803	                     ++element) {
2804	                    const float correction = (
2805	                        scaled_product.x[element]
2806	                        - high_product.x[element]
2807	                    ) * INVERSE_RESIDUAL_SCALE;
2808	                    accumulator.x[element] -=
2809	                        high_product.x[element] + correction;
2810	                }
2811	                wmma::store_matrix_sync(
2812	                    tile + (stop + block_row * MMA_M) * N
2813	                        + stop + block_col * MMA_N,
2814	                    accumulator,
2815	                    N,
2816	                    wmma::mem_row_major
2817	                );
2818	                }
2819	            }
2820	            ++ordinal;
2821	        }
2822	    }
2823	    if (warp == 0) {
2824	        factor_panel_16_warp(tile, stop);
2825	    }
2826	    __syncthreads();
2827	}
