2829	__global__ void blocked_wmma16_cholesky_128(
2830	    const float* __restrict__ input,
2831	    float* __restrict__ output
2832	) {
2833	    constexpr int N = 128;
2834	    extern __shared__ float tile[];
2835	    const int tid = threadIdx.x;
2836	    const long long base = static_cast<long long>(blockIdx.x) * N * N;
2837	    const float* src = input + base;
2838	    float* dst = output + base;
2839	    for (int vector = tid; vector < N * N / 4;
2840	         vector += blockDim.x) {
2841	        const int row = vector / (N / 4);
2842	        const int col = vector % (N / 4) * 4;
2843	        if (row >= col) {
2844	            float4 values = reinterpret_cast<const float4*>(src)[vector];
2845	            if (row < col + 3) values.w = 0.0f;
2846	            if (row < col + 2) values.z = 0.0f;
2847	            if (row < col + 1) values.y = 0.0f;
2848	            reinterpret_cast<float4*>(tile)[vector] = values;
2849	        }
2850	    }
2851	    __syncthreads();
2852	
2853	    factor_panel_16(tile, 0);
2854	    #pragma unroll
2855	    for (int panel = 0; panel < N; panel += 16) {
2856	        if (panel + 16 < N) {
2857	            solve_panel_16(tile, panel);
2858	            compensated_rankk_16(tile, panel);
2859	        }
2860	    }
2861	
2862	    for (int vector = tid; vector < N * N / 4;
2863	         vector += blockDim.x) {
2864	        const int row = vector / (N / 4);
2865	        const int col = vector % (N / 4) * 4;
2866	        if (row >= col) {
2867	            float4 values = reinterpret_cast<const float4*>(tile)[vector];
2868	            if (row < col + 3) values.w = 0.0f;
2869	            if (row < col + 2) values.z = 0.0f;
2870	            if (row < col + 1) values.y = 0.0f;
2871	            reinterpret_cast<float4*>(dst)[vector] = values;
2872	        }
2873	    }
2874	}
