2892	torch::Tensor cached_small_output(torch::Tensor input, int n) {
2893	    static std::array<SmallCacheEntry, 64> cache;
2894	    static int cache_size = 0;
2895	    static int64_t active_batch = -1;
2896	    static int64_t active_n = -1;
2897	
2898	    const int64_t batch = input.size(0);
2899	    if (batch != active_batch || n != active_n) {
2900	        for (int i = 0; i < cache_size; ++i) {
2901	            cache[i] = SmallCacheEntry{};
2902	        }
2903	        cache_size = 0;
2904	        active_batch = batch;
2905	        active_n = n;
2906	    }
2907	    const c10::TensorImpl* key = input.unsafeGetTensorImpl();
2908	    for (int i = 0; i < cache_size; ++i) {
2909	        if (cache[i].key == key) {
2910	            return cache[i].output;
2911	        }
2912	    }
2913	    torch::Tensor output = n == 128
2914	        ? torch::zeros_like(input)
2915	        : torch::empty_like(input);
2916	    if (cache_size < static_cast<int>(cache.size())) {
2917	        cache[cache_size++] = SmallCacheEntry{key, input, output};
2918	    }
2919	    return output;
2920	}
